#!/usr/bin/env bash
# Pydantic models (backend/app/models/schemas.py) -> frontend/src/types/api.ts
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
PY="${PYTHON:-$ROOT/.venv/bin/python}"
[ -x "$PY" ] || PY=python3
mkdir -p "$ROOT/frontend/src/types"
"$PY" "$ROOT/scripts/gen_types.py" > "$ROOT/frontend/src/types/api.schema.json"
cd "$ROOT/frontend"
npx json2ts -i src/types/api.schema.json -o src/types/api.ts --unreachableDefinitions --no-additionalProperties \
  --bannerComment "/* Generated by scripts/gen_types.sh from backend/app/models/schemas.py. Do not edit. */"
rm src/types/api.schema.json
echo "wrote frontend/src/types/api.ts"
